import json, collections, glob, statistics as st
import pyarrow.parquet as pq

tr = pq.read_table("/workspace/taco_verl/train.parquet").to_pandas()
te = pq.read_table("/workspace/taco_verl/test.parquet").to_pandas()

def gt_of(row):
    return json.loads(row["reward_model"]["ground_truth"])

def content_of(row):
    return row["prompt"][0]["content"]

def suite_leaks(row):
    """all tests of the suite appear verbatim in the prompt statement."""
    content = content_of(row)
    d = gt_of(row)
    for inp, out in zip(d["inputs"], d["outputs"]):
        si, so = str(inp).strip(), str(out).strip()
        if not (so and so in content and si and si in content):
            return False
    return True

def suite_leaks_strong(row):
    """all tests leak AND the leaked material is distinctive (non-trivial lengths)."""
    content = content_of(row)
    d = gt_of(row)
    for inp, out in zip(d["inputs"], d["outputs"]):
        si, so = str(inp).strip(), str(out).strip()
        if not (so and so in content and si and si in content):
            return False
        if len(so) < 4 and "\n" not in so and not so.isupper():
            return False  # outputs like '1', '2' match too easily
    return True

# ---------- full-suite leak counts by n_tests bucket, train and test ----------
def bucket(n):
    return ("1" if n == 1 else "2" if n == 2 else "3-5" if n <= 5
            else "6-10" if n <= 10 else "11-50" if n <= 50 else ">50")

for df, name in [(tr, "TRAIN"), (te, "TEST")]:
    rows_leak, rows_leak_strong = [], []
    for _, row in df.iterrows():
        if suite_leaks(row):
            rows_leak.append(row)
        if suite_leaks_strong(row):
            rows_leak_strong.append(row)
    cnt = collections.Counter(bucket(r["extra_info"]["n_tests"]) for r in rows_leak)
    cnts = collections.Counter(bucket(r["extra_info"]["n_tests"]) for r in rows_leak_strong)
    print(f"{name}: full-suite-leak rows = {len(rows_leak)}  by bucket: {dict(cnt)}")
    print(f"{name}: strong full-suite-leak rows = {len(rows_leak_strong)}  by bucket: {dict(cnts)}")
    print(f"{name}: total rows = {len(df)}; leak fraction = {len(rows_leak)/len(df):.3f}")

# ---------- how many leak rows total, and overlap with <=2-test ----------
leak_rows = [row for _, row in tr.iterrows() if suite_leaks(row)]
leak_ids = [row["extra_info"]["problem_id"] for row in leak_rows]
print("\ntrain leak ids (first 30):", leak_ids[:30])
print("distinct leak rows:", len(set(leak_ids)))
nt_of_leak = collections.Counter(row["extra_info"]["n_tests"] for row in leak_rows)
print("n_tests distribution of leak rows:", dict(sorted(nt_of_leak.items())))

# ---------- causal check from frozen dumps: leaked vs non-leaked rows ----------
leak_contents = set()
for row in leak_rows:
    leak_contents.add(content_of(row))
nonleak_onetest_contents = set()
for _, row in tr.iterrows():
    if row["extra_info"]["n_tests"] == 1 and content_of(row) not in leak_contents:
        nonleak_onetest_contents.add(content_of(row))

def find_content(inp):
    for c in leak_contents:
        if c in inp:
            return ("LEAK", c)
    for c in nonleak_onetest_contents:
        if c in inp:
            return ("NONLEAK_1T", c)
    return (None, None)

groups = collections.defaultdict(lambda: collections.defaultdict(list))  # tag -> input -> scores
rowlevel = collections.defaultdict(list)
for path in glob.glob("/workspace/rollout_data/*.jsonl"):
    rows = [json.loads(l) for l in open(path)]
    byin = collections.defaultdict(list)
    for r in rows:
        byin[r["input"]].append(r["score"])
    for inp, scores in byin.items():
        tag, c = find_content(inp)
        if tag:
            groups[tag][inp] = scores
            rowlevel[tag].extend(scores)

print("\nfrozen-run groups by row class:")
for tag, d in groups.items():
    ngroups = len(d)
    deg = sum(1 for s in d.values() if len(set(s)) == 1)
    solved = [st.mean(s) for s in d.values()]
    print(f"  {tag}: groups={ngroups} degenerate={deg/ngroups:.2f} mean_group_score={st.mean(solved):.3f}")
for tag, scores in rowlevel.items():
    print(f"  {tag}: rollout rows={len(scores)} mean score={st.mean(scores):.3f}")

# ---------- ground-truth contamination train<->test (fixed) ----------
tr_gts = set(r["ground_truth"] for r in tr["reward_model"])
te_gts = set(r["ground_truth"] for r in te["reward_model"])
print("\ntrain/test ground_truth exact overlap:", len(tr_gts & te_gts))
def io_sig(row):
    d = gt_of(row)
    return json.dumps([d["inputs"], d["outputs"]], sort_keys=True)
tr_io = set(io_sig(r) for _, r in tr.iterrows())
te_io = set(io_sig(r) for _, r in te.iterrows())
print("train/test full-suite overlap (same inputs+outputs):", len(tr_io & te_io))

# ---------- per-bucket pass_rate from dumps ----------
contents = {content_of(row): row["extra_info"]["n_tests"] for _, row in tr.iterrows()}
cache = {}
def ntests_of(inp):
    if inp not in cache:
        cache[inp] = next((n for c, n in contents.items() if c in inp), None)
    return cache[inp]

per_bucket = collections.defaultdict(lambda: [0, 0.0, 0.0, 0])
for path in glob.glob("/workspace/rollout_data/*.jsonl"):
    for l in open(path):
        r = json.loads(l)
        n = ntests_of(r["input"])
        if n is None:
            continue
        b = per_bucket[bucket(n)]
        b[0] += 1
        b[1] += r["score"]
        b[2] += r["pass_rate"]
        if r["pass_rate"] > 0:
            b[3] += 1
print("\nrollout rows by train n_tests bucket: n | mean score | mean pass_rate | frac rows pass_rate>0")
for k, (n, s, pr, pos) in sorted(per_bucket.items()):
    print(f"{k:>6}: {n:5d} | {s/n:.3f} | {pr/n:.3f} | {pos/n:.2f}")

